('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich nicht funktionale Anforderungen definiere?', 3, '[{"text": "Verfügbarkeit", "correct": false, "because": "Sichert Zugriff"}, {"text": "Wartbarkeit", "correct": false, "because": "Erleichtert Updates"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Anforderungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind nicht funktionale Anforderungen immer optional?', 3, '[{"text": "Nein", "correct": true, "because": "Oft essenziell"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
